// Generated derived rules of this version's subset (03-data-model/11-restricted-sql.md), for the
// property tests here and for the one that runs the printed rules on PGlite (store-pglite).
// Exported as `@fluxvita/saveslot-kernel/rsql-testing`; tests only.
//
// Rules are generated by type over `runs` (./rules.fixture.ts) with names in any ASCII case, quoted
// or not, qualified or not. The generator covers each form whose type PostgreSQL resolves
// differently from a plain reading (11 «类型»): numeric-only functions, sums of integers, 32-bit
// values (integer constants, length, strpos, date − date), constants in 32-bit-only positions
// (substr, left, right, split_part, round's digits, date ± days), and NULLs given a type by what is
// beside them. FORMS names them, each with a fixed rule that reaches it.

import fc from "fast-check";

export { Hits, propRuns } from "@fluxvita/saveslot-reference/testing";
// The parser and the whitelist's function lists, for tests that read the text a query is executed as.
export { rsqlParser } from "./load.ts";
export { derivedSchema, rule, TABLES, UNITS } from "./rules.fixture.ts";
// Random statements the checker accepts (and ones it refuses), over the slot `health`.
export { cleanStatement, type Generated, refusedStatement } from "./sql-generate.fixture.ts";
export { AGGREGATES, FUNCTIONS, WINDOW_FUNCTIONS } from "./whitelist.ts";
/** fast-check, for packages that run these rules without depending on it themselves. */
export { fc };

type Qual = "none" | "table" | "alias" | "slot";

interface Ctx {
  readonly qual: Qual;
}

const spell = (name: string): fc.Arbitrary<string> =>
  fc.constantFrom(
    name,
    name.toUpperCase(),
    `"${name}"`,
    `"${name.toUpperCase()}"`,
    name.charAt(0).toUpperCase() + name.slice(1),
  );

const col = (ctx: Ctx, name: string): fc.Arbitrary<string> =>
  fc.tuple(spell(name), fc.boolean()).map(([n, q]) => {
    if (!q || ctx.qual === "none") return n;
    if (ctx.qual === "alias") return `r.${n}`;
    if (ctx.qual === "slot") return `health.runs.${n}`;
    return `runs.${n}`;
  });

// --- literals ---------------------------------------------------------------------------------

const strLit = fc
  .string({
    unit: fc.constantFrom("a", "b", "'", "\\", "说", "\n", "%", "😀", " ", ","),
    maxLength: 6,
  })
  .map((s) => `'${s.replaceAll("'", "''")}'`);
const intLit = fc
  .oneof(
    { weight: 6, arbitrary: fc.integer({ min: -50, max: 500 }) },
    { weight: 1, arbitrary: fc.constantFrom(2000000000, -2147483648, 2147483647, 4000000000) },
  )
  .map(String);
const decLit = fc
  .tuple(fc.integer({ min: 0, max: 99 }), fc.integer({ min: 0, max: 999 }))
  .map(([a, b]) => `${a}.${b}`);
const numLit = fc.oneof(intLit, decLit);
/**
 * A LIKE pattern for escape `esc` ("" for none): text without the escape character, with escaped
 * `%`, `_` or escape characters put in, so that it never ends in a lone escape.
 */
const likePattern = (esc: string): fc.Arbitrary<string> =>
  fc
    .array(
      fc.oneof(
        fc.constantFrom("a", "b", "%", "_", "说", " ", "'", "😀"),
        ...(esc === "" ? [] : [fc.constantFrom(`${esc}%`, `${esc}_`, `${esc}${esc}`)]),
      ),
      { maxLength: 5 },
    )
    .map((xs) => `'${xs.join("").replaceAll("'", "''")}'`);

/** A 32-bit-only position's constant. */
const smallInt = (min: number, max: number) => fc.integer({ min, max }).map(String);

// --- typed expressions over `runs` ------------------------------------------------------------

/** A number; "km" ones carry the unit of `distance`. */
function num(ctx: Ctx, unit: "km" | "none", depth: number): fc.Arbitrary<string> {
  const leaves =
    unit === "km"
      ? [col(ctx, "distance")]
      : [
          col(ctx, "laps"),
          col(ctx, "pace"),
          numLit,
          col(ctx, "feeling").map((c) => `length(${c})`),
          fc.tuple(col(ctx, "feeling"), strLit).map(([c, s]) => `strpos(${c}, ${s})`),
          col(ctx, "date").map((c) => `(${c} - DATE '2026-01-01')`),
        ];
  if (depth <= 0) return fc.oneof(...leaves);
  const sub = num(ctx, unit, depth - 1);
  const subB = bool(ctx, depth - 1);
  /** numeric only: an integer is cast first. */
  const asNumeric = sub.map((a) => `(${a})::numeric(24, 4)`);
  const compound = [
    fc.tuple(sub, sub).map(([a, b]) => `${a} + ${b}`),
    fc.tuple(sub, sub).map(([a, b]) => `(${a}) - (${b})`),
    fc.tuple(sub, numLit).map(([a, b]) => `(${a}) * ${b}`),
    // A constant divisor is never 0: PostgreSQL folds constants when planning.
    fc.tuple(sub, decLit).map(([a, b]) => `(${a}) / ${Number(b) === 0 ? "1.5" : b}`),
    sub.map((a) => `abs(${a})`),
    fc.tuple(asNumeric, smallInt(-3, 6)).map(([a, d]) => `round(${a}, ${d})`),
    asNumeric.map((a) => `round(${a})`),
    fc
      .tuple(asNumeric, fc.option(smallInt(0, 4), { nil: undefined }))
      .map(([a, d]) => (d === undefined ? `trunc(${a})` : `trunc(${a}, ${d})`)),
    asNumeric.map((a) => `floor(${a})`),
    asNumeric.map((a) => `ceil(${a})`),
    sub.map((a) => `-(${a})`),
    fc.tuple(sub, numLit).map(([a, b]) => `COALESCE(${a}, ${b})`),
    sub.map((a) => `COALESCE(${a}, NULL)`),
    fc.tuple(sub, numLit).map(([a, b]) => `GREATEST(${a}, ${b})`),
    fc.tuple(subB, sub, sub).map(([c, a, b]) => `CASE WHEN ${c} THEN ${a} ELSE ${b} END`),
    fc.tuple(subB, sub).map(([c, a]) => `CASE WHEN ${c} THEN ${a} END`),
    fc.tuple(subB, sub).map(([c, a]) => `CASE WHEN ${c} THEN NULL ELSE ${a} END`),
    fc.tuple(sub, numLit).map(([a, b]) => `NULLIF(${a}, ${b})`),
    fc.tuple(sub, numLit).map(([a, b]) => `mod(${a}, ${Number(b) === 0 ? "7" : b})`),
    fc.tuple(sub, numLit).map(([a, b]) => `(${a}) % ${Number(b) === 0 ? "7" : b}`),
  ];
  if (unit === "none") {
    compound.push(
      col(ctx, "date").map((c) => `EXTRACT(month FROM ${c})`),
      col(ctx, "pace").map((c) => `sign(${c})`),
      asNumeric.map((a) => `sign(${a})`),
      fc.tuple(col(ctx, "laps"), col(ctx, "pace")).map(([a, b]) => `${a} * ${b}`),
      col(ctx, "pace").map((c) => `${c}::bigint::numeric(12, 2)`),
    );
  } else {
    compound.push(fc.tuple(sub, col(ctx, "laps")).map(([a, l]) => `(${a}) * ${l}`));
  }
  return fc.oneof({ depthSize: "small" }, ...leaves, ...compound);
}

function text(ctx: Ctx, depth: number): fc.Arbitrary<string> {
  const leaves = [col(ctx, "feeling"), col(ctx, "route"), strLit];
  if (depth <= 0) return fc.oneof(...leaves);
  const sub = text(ctx, depth - 1);
  return fc.oneof(
    { depthSize: "small" },
    ...leaves,
    fc.tuple(sub, smallInt(-3, 6)).map(([a, n]) => `substr(${a}, ${n})`),
    fc.tuple(sub, smallInt(-3, 6), smallInt(0, 5)).map(([a, n, m]) => `substr(${a}, ${n}, ${m})`),
    fc
      .tuple(sub, smallInt(-3, 6), smallInt(0, 5))
      .map(([a, n, m]) => `substring(${a} FROM ${n} FOR ${m})`),
    fc.tuple(sub, smallInt(-4, 4)).map(([a, n]) => `left(${a}, ${n})`),
    fc.tuple(sub, smallInt(-4, 4)).map(([a, n]) => `right(${a}, ${n})`),
    fc
      .tuple(sub, fc.oneof(smallInt(-3, -1), smallInt(1, 3)))
      .map(([a, n]) => `split_part(${a}, ',', ${n})`),
    fc.tuple(sub, sub).map(([a, b]) => `${a} || ${b}`),
    col(ctx, "feeling").map((c) => `${c} || NULL`),
    sub.map((a) => `btrim(${a})`),
    sub.map((a) => `trim(both 'x' from ${a})`),
    fc.tuple(sub, strLit, strLit).map(([a, b, c]) => `replace(${a}, ${b}, ${c})`),
    fc.tuple(sub, strLit).map(([a, b]) => `COALESCE(${a}, ${b})`),
    sub.map((a) => `COALESCE(${a}, NULL)`),
    fc.tuple(sub, strLit).map(([a, b]) => `NULLIF(${a}, ${b})`),
    fc
      .tuple(bool(ctx, depth - 1), sub, sub)
      .map(([c, a, b]) => `CASE WHEN ${c} THEN ${a} ELSE ${b} END`),
  );
}

function date(ctx: Ctx): fc.Arbitrary<string> {
  return fc.oneof(
    col(ctx, "date"),
    fc.tuple(col(ctx, "date"), smallInt(-400, 400)).map(([c, n]) => `${c} + ${n}`),
    fc.tuple(col(ctx, "date"), smallInt(0, 400)).map(([c, n]) => `${n} + ${c}`),
    fc.tuple(col(ctx, "date"), smallInt(-400, 400)).map(([c, n]) => `${c} - ${n}`),
    col(ctx, "date").map((c) => `date_trunc('week', ${c}::timestamp)::date`),
    col(ctx, "started").map((c) => `saveslot_date(${c})`),
    col(ctx, "date").map((c) => `COALESCE(${c}, NULL)`),
    fc.constant("DATE '2026-03-01'"),
  );
}

function bool(ctx: Ctx, depth: number): fc.Arbitrary<string> {
  const leaves: fc.Arbitrary<string>[] = [
    col(ctx, "race"),
    fc.tuple(col(ctx, "laps"), intLit).map(([a, b]) => `${a} > ${b}`),
    fc.tuple(col(ctx, "distance"), decLit).map(([a, b]) => `${a} <= ${b}`),
    fc.tuple(col(ctx, "feeling"), likePattern("\\")).map(([a, b]) => `${a} LIKE ${b}`),
    fc
      .constantFrom("", "!", "\\")
      .chain((e) => fc.tuple(col(ctx, "feeling"), likePattern(e), fc.constant(e)))
      .map(([a, b, e]) => `${a} NOT LIKE ${b} ESCAPE '${e}'`),
    fc
      .tuple(col(ctx, "laps"), fc.array(intLit, { minLength: 1, maxLength: 4 }))
      .map(([a, xs]) => `${a} IN (${xs.join(", ")})`),
    fc
      .tuple(col(ctx, "laps"), fc.array(intLit, { minLength: 1, maxLength: 3 }))
      .map(([a, xs]) => `${a} NOT IN (${xs.join(", ")}, NULL)`),
    fc.tuple(col(ctx, "pace"), decLit, decLit).map(([a, b, c]) => `${a} NOT BETWEEN ${b} AND ${c}`),
    col(ctx, "laps").map((a) => `${a} IS NULL`),
    col(ctx, "race").map((a) => `${a} IS NOT TRUE`),
    col(ctx, "feeling").map((a) => `${a} = NULL`),
    fc
      .tuple(col(ctx, "date"), fc.constantFrom("'2026-01-01'", "DATE '2026-12-31'"))
      .map(([a, b]) => `${a} >= ${b}`),
    fc
      .tuple(
        col(ctx, "started"),
        fc.constantFrom("'2026-01-01T00:00:00Z'", "'2026-06-01 08:00:00+08:00'"),
      )
      .map(([a, b]) => `${a} < ${b}`),
    fc.tuple(col(ctx, "route"), strLit).map(([a, b]) => `starts_with(${a}, ${b})`),
    fc.tuple(col(ctx, "laps"), intLit).map(([a, b]) => `${a} IS DISTINCT FROM ${b}`),
    fc.tuple(col(ctx, "date"), date(ctx)).map(([a, b]) => `${a} < ${b}`),
  ];
  if (depth <= 0) return fc.oneof(...leaves);
  const sub = bool(ctx, depth - 1);
  return fc.oneof(
    { depthSize: "small" },
    ...leaves,
    sub.map((a) => `NOT (${a})`),
    fc.tuple(sub, sub).map(([a, b]) => `(${a}) AND (${b})`),
    fc.tuple(sub, sub).map(([a, b]) => `(${a}) OR (${b})`),
    fc.tuple(num(ctx, "km", depth - 1), num(ctx, "km", depth - 1)).map(([a, b]) => `${a} > ${b}`),
    fc
      .tuple(num(ctx, "none", depth - 1), num(ctx, "none", depth - 1))
      .map(([a, b]) => `${a} = ${b}`),
  );
}

export interface GeneratedRule {
  readonly sql: string;
  readonly fields: string[];
  readonly timeDependency: "none" | "bucketed" | "now";
}

/** An aggregate output, by type. */
function aggregate(ctx: Ctx): fc.Arbitrary<string> {
  const filter = fc
    .option(bool(ctx, 1), { nil: undefined })
    .map((b) => (b === undefined ? "" : ` FILTER (WHERE ${b})`));
  return fc
    .tuple(
      fc.oneof(
        fc.constant("count(*)"),
        text(ctx, 1).map((x) => `count(${x})`),
        col(ctx, "route").map((x) => `count(DISTINCT ${x})`),
        num(ctx, "km", 2).map((x) => `sum(${x})`),
        num(ctx, "none", 2).map((x) => `sum(${x})`),
        col(ctx, "laps").map((x) => `sum(${x})`),
        num(ctx, "km", 1).map((x) => `avg(${x})`),
        num(ctx, "none", 1).map((x) => `max(${x})`),
        text(ctx, 1).map((x) => `min(${x})`),
        // The numeric-only functions, directly on a column or a cast integer.
        fc
          .tuple(
            fc.constantFrom("round", "trunc", "floor", "ceil", "sign"),
            fc.oneof(
              col(ctx, "pace"),
              col(ctx, "laps").map((c) => `${c}::numeric`),
            ),
          )
          .map(([f, x]) => `max(${f}(${x}))`),
        // The 32-bit-only text functions, directly on a column.
        fc
          .tuple(
            col(ctx, "feeling"),
            fc.constantFrom("left", "right", "split_part", "substr"),
            smallInt(-3, 4),
          )
          .map(([c, f, n]) =>
            f === "split_part"
              ? `max(split_part(${c}, ',', ${n === "0" ? "1" : n}))`
              : `max(${f}(${c}, ${n}))`,
          ),
        date(ctx).map((x) => `max(${x})`),
        date(ctx).map((x) => `min(${x} - DATE '2026-01-01')`),
        bool(ctx, 1).map((x) => `bool_or(${x})`),
      ),
      filter,
    )
    .map(([a, f]) => a + f)
    .chain((a) =>
      a.startsWith("sum(") ? fc.constantFrom(a, `COALESCE(${a}, 0)`) : fc.constant(a),
    );
}

const KEYS: readonly {
  readonly expr: (ctx: Ctx) => fc.Arbitrary<string>;
  readonly bucket: boolean;
}[] = [
  { expr: (c) => col(c, "route"), bucket: false },
  { expr: (c) => col(c, "feeling").map((x) => `substr(${x}, 1, 2)`), bucket: false },
  { expr: (c) => col(c, "laps"), bucket: false },
  { expr: (c) => col(c, "race"), bucket: false },
  { expr: (c) => col(c, "date"), bucket: true },
  {
    expr: (c) => col(c, "date").map((x) => `date_trunc('month', ${x}::timestamp)::date`),
    bucket: true,
  },
  { expr: (c) => col(c, "started").map((x) => `saveslot_date(${x})`), bucket: true },
  // Reading a date is no bucket by itself (11 «时间»).
  { expr: (c) => col(c, "date").map((x) => `EXTRACT(year FROM ${x})`), bucket: false },
  { expr: (c) => col(c, "date").map((x) => `${x} + 1`), bucket: false },
];

/** A rule of this version's subset, its declared fields and its time dependency. */
export const generatedRule: fc.Arbitrary<GeneratedRule> = fc
  .record({
    qual: fc.constantFrom<Qual>("none", "table", "alias", "slot"),
    key: fc.option(fc.constantFrom(...KEYS), { nil: undefined, freq: 4 }),
    byOrdinal: fc.boolean(),
    today: fc.boolean(),
    count: fc.integer({ min: 1, max: 3 }),
    semicolon: fc.boolean(),
  })
  .chain((g) => {
    const ctx: Ctx = { qual: g.qual };
    return fc
      .record({
        key: g.key === undefined ? fc.constant(undefined) : g.key.expr(ctx),
        aggs: fc.array(aggregate(ctx), { minLength: g.count, maxLength: g.count }),
        where: fc.option(bool(ctx, 2), { nil: undefined }),
        having: fc.option(fc.constantFrom("count(*) > 1", "count(*) >= 0 OR bool_or(race)"), {
          nil: undefined,
        }),
      })
      .map((p): GeneratedRule => {
        const from = g.qual === "alias" ? "runs AS r" : g.qual === "slot" ? "health.runs" : "runs";
        const outs = [
          ...(p.key !== undefined ? [`${p.key} AS k`] : []),
          ...p.aggs.map((a, i) => `${a} AS a${i}`),
        ];
        const where = [p.where, g.today ? "date > saveslot_today() - 30" : undefined].filter(
          (x) => x !== undefined,
        );
        const group = p.key === undefined ? "" : ` GROUP BY ${g.byOrdinal ? "1" : p.key}`;
        const sql = `SELECT ${outs.join(", ")} FROM ${from}${where.length > 0 ? ` WHERE ${where.map((w) => `(${w})`).join(" AND ")}` : ""}${group}${p.having !== undefined ? ` HAVING ${p.having}` : ""}${g.semicolon ? ";" : ""}`;
        return {
          sql,
          fields: [...(p.key !== undefined ? ["k"] : []), ...p.aggs.map((_, i) => `a${i}`)],
          timeDependency: g.today ? "now" : g.key?.bucket ? "bucketed" : "none",
        };
      });
  });

/** A rule of one aggregate output `a0` over `runs`, with no time dependency. */
const one = (agg: string): GeneratedRule => ({
  sql: `SELECT ${agg} AS a0 FROM runs`,
  fields: ["a0"],
  timeDependency: "none",
});

/**
 * The forms whose types PostgreSQL resolves differently from a plain reading, by what the rule as
 * written (`sql`) or its bound text (`bound`) shows; each with a fixed rule that reaches it, so
 * that every form is checked on every run whatever the generator draws.
 */
export const FORMS: readonly {
  readonly name: string;
  readonly reached: (sql: string, bound: string) => boolean;
  readonly example: GeneratedRule;
}[] = [
  { name: "round", reached: (s) => /\bround\(/i.test(s), example: one("max(round(pace))") },
  {
    name: "trunc",
    reached: (s) => /\btrunc\(/i.test(s),
    example: one("max(trunc(laps::numeric))"),
  },
  { name: "floor", reached: (s) => /\bfloor\(/i.test(s), example: one("max(floor(pace))") },
  { name: "ceil", reached: (s) => /\bceil\(/i.test(s), example: one("max(ceil(pace))") },
  { name: "sign", reached: (s) => /\bsign\(/i.test(s), example: one("max(sign(pace))") },
  {
    name: "sum of integers",
    reached: (_, b) => b.includes("CAST(sum("),
    example: one("sum(laps)"),
  },
  {
    name: "integer constant",
    reached: (_, b) => /CAST\(-?\d+ AS bigint\)/.test(b),
    example: one("count(*) FILTER (WHERE laps IS DISTINCT FROM 3)"),
  },
  {
    name: "length",
    reached: (_, b) => b.includes("CAST(length("),
    example: one("max(length(feeling))"),
  },
  {
    name: "strpos",
    reached: (_, b) => b.includes("CAST(strpos("),
    example: one("max(strpos(feeling, 'a'))"),
  },
  {
    name: "date - date",
    reached: (_, b) => /CAST\(\("t1"\."f1" - /.test(b),
    example: one("min(date - DATE '2026-01-01')"),
  },
  {
    name: "substr",
    reached: (_, b) => b.includes("substr("),
    example: one("max(substr(feeling, 2))"),
  },
  { name: "left", reached: (_, b) => b.includes("left("), example: one("max(left(feeling, -1))") },
  {
    name: "right",
    reached: (_, b) => b.includes("right("),
    example: one("max(right(feeling, 3))"),
  },
  {
    name: "split_part",
    reached: (_, b) => b.includes("split_part("),
    example: one("max(split_part(feeling, ',', 2))"),
  },
  {
    name: "date ± days",
    reached: (_, b) => /"t1"\."f1" [+-] -?\d+\)|\(-?\d+ \+ "t1"\."f1"\)/.test(b),
    example: one("max(date + 1)"),
  },
  // A NULL value, not an IS [NOT] NULL test.
  {
    name: "NULL",
    reached: (_, b) => /(?<!IS |IS NOT )NULL\b/.test(b),
    example: one("count(*) FILTER (WHERE feeling = NULL)"),
  },
];
